#include <vector>
#include <unordered_set>
#include <string>
using namespace std;

class Solution {
public:
    int countDistinctIntegers(vector<int>& nums) {
        unordered_set<long long> seen;
        for (int x : nums) {
            string s = to_string(x);
            string clean = "";
            for (char c : s) if (c != '0') clean += c;
            long long val = clean.empty() ? 0 : stoll(clean);
            seen.insert(val);
        }
        return seen.size();
    }
};

import java.util.*;

class Solution {
    public int countDistinctIntegers(int[] nums) {
        Set<Long> seen = new HashSet<>();
        for (int x : nums) {
            String s = Integer.toString(x).replace("0", "");
            long val = s.isEmpty() ? 0 : Long.parseLong(s);
            seen.add(val);
        }
        return seen.size();
    }
}

var countDistinctIntegers = function(nums) {
    const seen = new Set();
    for (const x of nums) {
        const s = String(x).replace(/0/g, '');
        const val = s.length === 0 ? 0 : Number(s);
        seen.add(val);
    }
    return seen.size;
};
